import importlib.util,pathlib,tarfile
root=pathlib.Path(importlib.util.find_spec('openvino').origin).parent
with tarfile.open('/validation/openvino-typing.tar','w') as out:
    for path in root.rglob('*'):
        if path.is_file() and (path.suffix in {'.py','.pyi'} or path.name=='py.typed'):out.add(path,arcname='openvino/'+path.relative_to(root).as_posix())
print('OpenVINO typing source:',root)
